// Generated by scripts/derive-overrides.mjs from packages/mobile-core/src/screens/invitation-screen.tsx. Do not edit.
import { useRouter } from 'expo-router';
import { useEffect, useState } from 'react';
import { ActivityIndicator, View } from 'react-native';

import { authClient } from '@kuvos/mobile-core/auth-client';
import { api, type CareRole, type Me, type PendingInvitation } from '@kuvos/mobile-core/api';
import { Button } from '@kuvos/mobile-core/components/button';
import { DeleteAccountButton } from '@kuvos/mobile-core/components/delete-account';
import { Screen } from '@kuvos/mobile-core/components/screen';
import { Text, TextInput } from '@kuvos/mobile-core/components/text';

export function InvitationScreen({ invitationId }: { invitationId?: string }) {
  const router = useRouter();
  const [invitation, setInvitation] = useState<PendingInvitation>();
  const [name, setName] = useState('');
  const [loaded, setLoaded] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [account, setAccount] = useState<{
    role: CareRole;
    patientName: string;
  }>();

  useEffect(() => {
    api<Me>('/me')
      .then((me) => {
        const next = invitationId
          ? me.pendingInvitations.find(({ id }) => id === invitationId)
          : me.pendingInvitations[0];
        setInvitation(next);
        if (!next) {
          setError(
            'This invitation is unavailable for this account. Sign in with the email address that received it.',
          );
        }
        if (me.user.name !== 'Kuvos user') {
          setName(me.user.name);
        }
        const patientMembership = me.memberships.find(
          (membership) => membership.role === 'PATIENT',
        );
        const membership = patientMembership ?? me.memberships[0];
        if (membership) {
          setAccount({
            role: membership.role,
            patientName: membership.patient.name,
          });
        }
      })
      .catch((caught) =>
        setError(caught instanceof Error ? caught.message : 'Could not load invitation.'),
      )
      .finally(() => setLoaded(true));
  }, [invitationId]);

  async function accept() {
    if (!invitation || busy) return;
    setBusy(true);
    setError('');
    try {
      await api(`/invitations/${invitation.id}/accept`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      router.replace('/');
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The invitation could not be accepted.');
    } finally {
      setBusy(false);
    }
  }

  async function decline() {
    if (!invitation || busy) return;
    setBusy(true);
    setError('');
    try {
      await api(`/invitations/${invitation.id}/decline`, { method: 'POST' });
      router.replace('/');
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'The invitation could not be declined.');
    } finally {
      setBusy(false);
    }
  }

  async function useAnotherAccount() {
    await authClient.signOut();
    router.replace(invitationId ? { pathname: '/sign-in', params: { invitationId } } : '/sign-in');
  }

  return (
    <Screen>
      {!loaded && <ActivityIndicator className="m-auto" />}
      {invitation && (
        <>
          <View className="items-center gap-6 py-10">
            <View className="h-20 w-20 items-center justify-center rounded-full bg-deep-blue"><Text className="font-serif text-3xl text-white">{invitation.invitedBy.name.slice(0, 1).toUpperCase()}</Text></View>
            <Text className="text-center font-hand text-2xl text-slate">One check-in, closer together.</Text>
            <Text selectable className="text-3xl font-serif text-deep-blue">
              {invitation.invitedBy.name} invited you to {invitation.patient.name}’s care routine
            </Text>
            <Text selectable className="text-base leading-6 text-slate">
              {invitation.invitedBy.name} invited you as a {invitation.role.toLowerCase()}.
            </Text>
          </View>
          <View className="gap-4 rounded-3xl border border-line bg-white p-5">
            <Text selectable className="font-bold text-deep-blue">
              Your name
            </Text>
            <TextInput
              autoFocus
              blurOnSubmit={false}
              editable={!busy}
              accessibilityLabel="Your name"
              autoCapitalize="words"
              className="min-h-14 rounded-2xl border border-line bg-cloud px-4 text-base text-ink"
              maxLength={80}
              onChangeText={setName}
              onSubmitEditing={accept}
              returnKeyType="done"
              autoComplete="name"
              value={name}
            />
            <Button loading={busy} title="Join Care Circle" onPress={accept} />
            <Button disabled={busy} title="Decline" variant="quiet" onPress={decline} />
          </View>
        </>
      )}
      {loaded && (
        <View className="mt-auto pt-6">
          <DeleteAccountButton membership={account} />
        </View>
      )}
      {!!error && (
        <View className="gap-4 rounded-3xl bg-coral/15 p-5">
          <Text selectable accessibilityRole="alert" className="text-ink">
            {error}
          </Text>
          {loaded && !invitation ? (
            <Button title="Use another account" variant="quiet" onPress={useAnotherAccount} />
          ) : null}
        </View>
      )}
    </Screen>
  );
}
